This sample shows how to call GetPolicyAsync and parse the result.

Uri endpoint = new Uri("<endpoint>");
TokenCredential credential = new DefaultAzureCredential();
Policy client = new AttestationClient(endpoint, credential).GetPolicyClient(apiVersion: "2025-06-01");

Response response = await client.GetPolicyAsync("SgxEnclave");

JsonElement result = JsonDocument.Parse(response.ContentStream).RootElement;
Console.WriteLine(result.ToString());

